def transform(grid):
    sep = next(c for c in range(len(grid[0]))
               if all(row[c] == grid[0][c] for row in grid))
    left = [row[:sep] for row in grid]
    from collections import Counter
    bg = Counter(x for row in left for x in row).most_common(1)[0][0]
    return [[3 if x != bg else 4 for x in row] for row in left]
